data.transform:
// Grab variables
sourceAvilable = $state.context.Request.inventory;
possibleCuts = $state.context.Request.workOrderProcesses;
suggestedCuts = $;

// create a list for fulfilled workorders
fulfilled = []

// prep return
finalCuts = []

// loop source material
for (x = 0; x < suggestedCuts.length; x++) {
  // grab next source
  currentSource = sourceAvilable[x];

  // grab the next suggested cut
  suggestedCut = suggestedCuts[x];

  myCuts = []
  cutList = suggestedCut.cuts.split(',');
  for (y=0; y < cutList.length; y++) {
    cut = cutList[y];

    for (z=0; z < possibleCuts.length; z++) {
      possible = possibleCuts[z];
      possibleStdUsage = Math.ceil(possible.standardUsage*100).toString();
      if (cut==possibleStdUsage) {
        if (!fulfilled.includes(possible.id)) {
          fulfilled.push(possible.id)
          myCuts.push(possible)
          break;
        }
      }
    }
  }

  finalCuts.push({
    "source": currentSource,
    "suggestedCut": suggestedCut,
    "myCuts":  myCuts
  })
}

return finalCuts

